#!/usr/bin/env python3
# -*- coding: ascii -*-
"""
Patch de reconciliation M1 (BlokQR) : retablit le decoupage des paliers dans
app/pipeline.py.
  (a) ajoute le parametre 'deep: bool = False' a analyze() ;
  (b) separe la cle de cache par palier (fast/deep) sans toucher cache_key() ;
  (c) remplace le bloc unique par deux branches :
        - else (GRATUIT/RAPIDE) : threat intel + age du domaine, SANS rendu ;
        - if deep (PRO)         : rendu Chromium + threat intel + age du domaine.
Les routes sont deja correctes (/v1/analyze -> deep defaut False ;
/v1/analyze/deep -> deep=True). Idempotent, abort si ancre absente, AST validee.
Lancer depuis /opt/blokqr/backend.
"""
import ast, base64, os, sys

def d(s): return base64.b64decode(s).decode("utf-8")

PATH = "app/pipeline.py"
EDITS = [
    ("YXN5bmMgZGVmIGFuYWx5emUoCiAgICByZXF1ZXN0OiBBbmFseXplUmVxdWVzdCwgc2V0dGluZ3M6IFNldHRpbmdzLCBzaWduZXI6IFZlcmRpY3RTaWduZXIKKSAtPiBTaWduZWRWZXJkaWN0OgogICAgIiIiRXjDqWN1dGUgbGUgcGlwZWxpbmUgY29tcGxldCBldCByZW52b2llIHVuIHZlcmRpY3Qgc2lnbsOpLiIiIgo=", ""),
    ("ICAgIGNhY2hlID0gZ2V0X2NhY2hlKHNldHRpbmdzKQogICAgY2tleSA9IGNhY2hlX2tleShyZXF1ZXN0KQo=", "ICAgIGNhY2hlID0gZ2V0X2NhY2hlKHNldHRpbmdzKQogICAgY2tleSA9ICgiZGVlcDoiIGlmIGRlZXAgZWxzZSAiZmFzdDoiKSArIHN0cihjYWNoZV9rZXkocmVxdWVzdCkpCg=="),
    ("", ""),
]

def main():
    if not os.path.exists(PATH):
        print("[ABORT] %s introuvable" % PATH); sys.exit(1)
    src = open(PATH, encoding="utf-8").read()

    if "from app.analyzers.domain_age import domain_age_signal" not in src:
        print("[ABORT] import domain_age_signal absent : appliquez d'abord patch_domain_age.py")
        sys.exit(1)

    applied = 0
    for i, (old_b, new_b) in enumerate(EDITS, 1):
        old, new = d(old_b), d(new_b)
        if new in src:
            print("[SKIP] edition %d : deja appliquee" % i); continue
        if old not in src:
            print("[ABORT] edition %d : ancre introuvable -> AUCUNE ecriture" % i)
            sys.exit(1)
        src = src.replace(old, new, 1)
        applied += 1
        print("[OK]   edition %d appliquee" % i)

    if applied:
        ast.parse(src)  # validation globale avant ecriture
        with open(PATH, "w", encoding="utf-8") as f:
            f.write(src)
        print("\n[OK] %s reconcilie (%d edition(s)). Reconstruisez le conteneur." % (PATH, applied))
    else:
        print("\nRien a faire (deja reconcilie).")

if __name__ == "__main__":
    main()
